-- Name: AccountingOutbox; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE IF NOT EXISTS platform."AccountingOutbox" (
    "Id" uuid NOT NULL,
    "TenantId" bigint NOT NULL,
    "SubscriptionInvoiceId" bigint NOT NULL,
    "MessageType" character varying(64) NOT NULL,
    "IdempotencyKey" character varying(160) NOT NULL,
    "PayloadJson" jsonb NOT NULL,
    "PayloadSha256" character(64) NOT NULL,
    "Status" character varying(24) NOT NULL,
    "ReconciliationStatus" character varying(32) NOT NULL,
    "AttemptCount" integer NOT NULL,
    "MaxAttempts" integer NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    "AvailableAtUtc" timestamp with time zone NOT NULL,
    "LastAttemptAtUtc" timestamp with time zone,
    "LeaseExpiresAtUtc" timestamp with time zone,
    "LeaseToken" uuid,
    "WorkerId" character varying(128),
    "LastFailureCode" character varying(64),
    "ExternalReference" character varying(256),
    "ExternalReceiptSha256" character(64),
    "AcknowledgedAtUtc" timestamp with time zone,
    "AcknowledgedBy" character varying(256),
    "RedrivenAtUtc" timestamp with time zone,
    "RedrivenBy" character varying(256),
    "RedriveReason" character varying(1000),
    "SubscriptionRevenueActionId" bigint,
    CONSTRAINT "CK_AccountingOutbox_Acknowledgement" CHECK ((((("Status")::text = 'Acknowledged'::text) AND ("AcknowledgedAtUtc" IS NOT NULL) AND ("ExternalReference" IS NOT NULL) AND ("ExternalReceiptSha256" IS NOT NULL) AND (("ReconciliationStatus")::text = 'Reconciled'::text)) OR (("Status")::text <> 'Acknowledged'::text))),
    CONSTRAINT "CK_AccountingOutbox_Attempts" CHECK ((("MaxAttempts" > 0) AND ("AttemptCount" >= 0) AND ("AttemptCount" <= "MaxAttempts"))),
    CONSTRAINT "CK_AccountingOutbox_Lease" CHECK ((((("Status")::text = 'InFlight'::text) AND ("LeaseToken" IS NOT NULL) AND ("LeaseExpiresAtUtc" IS NOT NULL) AND ("WorkerId" IS NOT NULL)) OR ((("Status")::text <> 'InFlight'::text) AND ("LeaseToken" IS NULL) AND ("LeaseExpiresAtUtc" IS NULL) AND ("WorkerId" IS NULL)))),
    CONSTRAINT "CK_AccountingOutbox_PayloadHash" CHECK (("PayloadSha256" ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT "CK_AccountingOutbox_ReceiptHash" CHECK ((("ExternalReceiptSha256" IS NULL) OR ("ExternalReceiptSha256" ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT "CK_AccountingOutbox_Reconciliation" CHECK (("ReconciliationStatus"  = ANY (ARRAY['NotSent'::character varying, 'AwaitingAcknowledgement'::character varying, 'Reconciled'::character varying, 'Exception'::character varying]))),
    CONSTRAINT "CK_AccountingOutbox_Status" CHECK (("Status"  = ANY (ARRAY['Pending'::character varying, 'InFlight'::character varying, 'RetryScheduled'::character varying, 'Acknowledged'::character varying, 'Poison'::character varying])))
);

ALTER TABLE ONLY platform."AccountingOutbox" FORCE ROW LEVEL SECURITY;


