    CONSTRAINT "CK_SubscriptionRevenueActions_Value" CHECK ((((("Kind")::text = 'Dunning'::text) AND ("Amount" = (0)::numeric)) OR ((("Kind")::text <> 'Dunning'::text) AND ("Amount" > (0)::numeric))))
