    CONSTRAINT "CK_UsageEvents_Rating" CHECK ((("AllowanceApplied" >= (0)::numeric) AND ("AllowanceApplied" <= GREATEST("Quantity", (0)::numeric)) AND (("UnitPrice" IS NULL) OR ("UnitPrice" >= (0)::numeric)))),
    CONSTRAINT "CK_UsageEvents_RatingStatus" CHECK (("RatingStatus"  = ANY (ARRAY['Pending'::character varying, 'Ready'::character varying, 'BlockedUncertifiedMeter'::character varying, 'Rated'::character varying])))
