    CONSTRAINT "CK_AccountingPeriods_Range" CHECK ("FiscalYear" BETWEEN 2000 AND 2200 AND "PeriodNumber" BETWEEN 1 AND 99 AND "StartsOn" <= "EndsOn"),
    CONSTRAINT "CK_AccountingPeriods_Status" CHECK (("Status"  = ANY (ARRAY['Open'::character varying, 'SoftClosed'::character varying, 'Closed'::character varying])))
);

