--
-- Name: AiProcessingPolicies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public."AiProcessingPolicies" (
    "BusinessUnitId" bigint NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "ExternalProcessingAllowed" boolean NOT NULL,
    "AllowedPurposes" character varying(500) NOT NULL,
    "AllowedProvider" character varying(100),
    "AllowedModel" character varying(255),
    "MonthlySoftTokenLimit" bigint,
    "MonthlyHardTokenLimit" bigint,
    "Version" bigint DEFAULT 1 NOT NULL,
    "UpdatedOn" timestamp without time zone NOT NULL,
    "UpdatedBy" character varying(255) NOT NULL,
    "ExternalCostCurrency" character varying(3),
    "ExternalInputCostPerMillionTokens" numeric(18,6),
    "ExternalOutputCostPerMillionTokens" numeric(18,6),
    "ExternalPricingVersion" character varying(100),
    "MaxTokensPerDocument" bigint,
    "AllowedDataClassifications" character varying(300) DEFAULT 'Public,Internal'::character varying NOT NULL,
    "DataResidency" character varying(100) DEFAULT 'TenantApprovedRegion'::character varying NOT NULL,
    "EgressPolicy" character varying(100) DEFAULT 'RedactedFieldsOnly'::character varying NOT NULL,
    "ExternalDependencyCeilingPercent" numeric(5,2) DEFAULT 10.0 NOT NULL,
    "InputOutputAuditAllowed" boolean DEFAULT false NOT NULL,
    "LocalComputeCostPerHour" numeric(18,6),
    "LocalCostCurrency" character varying(3),
    "OcrCostPerPage" numeric(18,6),
    "PrivacyReviewRequired" boolean DEFAULT true NOT NULL,
    "RedactionRequired" boolean DEFAULT true NOT NULL,
    "RetentionDays" integer DEFAULT 30 NOT NULL,
    CONSTRAINT "CK_AiProcessingPolicies_DocumentBudget" CHECK ((("MaxTokensPerDocument" IS NULL) OR ("MaxTokensPerDocument" > 0))),
    CONSTRAINT "CK_AiProcessingPolicies_ExternalRates" CHECK (((("ExternalInputCostPerMillionTokens" IS NULL) AND ("ExternalOutputCostPerMillionTokens" IS NULL) AND ("ExternalCostCurrency" IS NULL) AND ("ExternalPricingVersion" IS NULL)) OR (("ExternalInputCostPerMillionTokens" >= (0)::numeric) AND ("ExternalOutputCostPerMillionTokens" >= (0)::numeric) AND (("ExternalCostCurrency")::text ~ '^[A-Z]{3}$'::text) AND (length(TRIM(BOTH FROM "ExternalPricingVersion")) > 0)))),
    CONSTRAINT "CK_AiProcessingPolicies_LocalRates" CHECK (((("LocalComputeCostPerHour" IS NULL) AND ("OcrCostPerPage" IS NULL) AND ("LocalCostCurrency" IS NULL)) OR (("LocalComputeCostPerHour" >= (0)::numeric) AND ("OcrCostPerPage" >= (0)::numeric) AND (("LocalCostCurrency")::text ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT "CK_AiProcessingPolicies_TokenLimits" CHECK (((("MonthlySoftTokenLimit" IS NULL) OR ("MonthlySoftTokenLimit" >= 0)) AND (("MonthlyHardTokenLimit" IS NULL) OR ("MonthlyHardTokenLimit" >= 0)) AND (("MonthlySoftTokenLimit" IS NULL) OR ("MonthlyHardTokenLimit" IS NULL) OR ("MonthlySoftTokenLimit" <= "MonthlyHardTokenLimit")))),
    CONSTRAINT "CK_AiProcessingPolicies_TrustControls" CHECK ("ExternalDependencyCeilingPercent" BETWEEN 0 AND 10
        AND "RetentionDays" BETWEEN 1 AND 3650
        AND length(trim("AllowedDataClassifications")) > 0
        AND length(trim("EgressPolicy")) > 0
        AND length(trim("DataResidency")) > 0
        AND (NOT "ExternalProcessingAllowed"
             OR ("RedactionRequired" AND "PrivacyReviewRequired"
                 AND "AllowedProvider" IS NOT NULL AND "AllowedModel" IS NOT NULL)))
);

ALTER TABLE ONLY public."AiProcessingPolicies" FORCE ROW LEVEL SECURITY;


