--
-- Name: LedgerAccounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public."LedgerAccounts" (
    "Id" bigint NOT NULL,
    "BusinessUnitId" bigint NOT NULL,
    "Code" character varying(30) NOT NULL,
    "Name" character varying(160) NOT NULL,
    "Category" character varying(20) NOT NULL,
    "NormalBalance" character varying(10) NOT NULL,
    "CurrencyId" bigint,
    "IsControlAccount" boolean NOT NULL,
    "AllowsManualPosting" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "IdempotencyKey" character varying(128) NOT NULL,
    "RequestHash" character varying(64) NOT NULL,
    "Version" bigint NOT NULL,
    "CreatedBy" character varying(255) NOT NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "DeactivatedBy" character varying(255),
    "DeactivatedOn" timestamp without time zone,
    "DeactivationReason" character varying(500),
    "IsContraAccount" boolean DEFAULT false NOT NULL,
    CONSTRAINT "CK_LedgerAccounts_State" CHECK ((((("Category"  = ANY (ARRAY['Asset'::character varying, 'Expense'::character varying])) AND (((NOT "IsContraAccount") AND (("NormalBalance")::text = 'Debit'::text)) OR ("IsContraAccount" AND (("NormalBalance")::text = 'Credit'::text)))) OR (("Category"  = ANY (ARRAY['Liability'::character varying, 'Equity'::character varying, 'Revenue'::character varying])) AND (((NOT "IsContraAccount") AND (("NormalBalance")::text = 'Credit'::text)) OR ("IsContraAccount" AND (("NormalBalance")::text = 'Debit'::text))))) AND (("IsActive" AND ("DeactivatedBy" IS NULL) AND ("DeactivatedOn" IS NULL) AND ("DeactivationReason" IS NULL)) OR ((NOT "IsActive") AND ("DeactivatedBy" IS NOT NULL) AND ("DeactivatedOn" IS NOT NULL) AND (length(TRIM(BOTH FROM "DeactivationReason")) >= 20)))))
);

ALTER TABLE ONLY public."LedgerAccounts" FORCE ROW LEVEL SECURITY;


