    "BusinessUnitId" bigint NOT NULL,
    "CommercialExceptionCaseId" bigint NOT NULL,
    "FromStatus" character varying(24),
    "ToStatus" character varying(24) NOT NULL,
    "FromVersion" bigint NOT NULL,
    "ToVersion" bigint NOT NULL,
    "ActionCode" character varying(100) NOT NULL,
    "Reason" character varying(1000) NOT NULL,
    "ActorId" character varying(160) NOT NULL,
    "OccurredAtUtc" timestamp without time zone NOT NULL,
    "CorrelationId" character varying(100) NOT NULL,
    "IdempotencyKey" character varying(160) NOT NULL,
    "RequestHash" character varying(64) NOT NULL,
    CONSTRAINT "CK_commercial_exception_events_ActionStatus" CHECK ((((("ActionCode")::text = 'DETECTED'::text) AND ("FromStatus" IS NULL) AND ("FromVersion" = 0) AND (("ToStatus")::text = 'Open'::text) AND ("ToVersion" = 1)) OR ((("ActionCode")::text = 'REFRESHED'::text) AND ("FromStatus" IS NOT NULL) AND (("ToStatus")::text = ("FromStatus")::text)) OR ((("ActionCode")::text = 'ACKNOWLEDGE'::text) AND (("FromStatus")::text = 'Open'::text) AND (("ToStatus")::text = 'Acknowledged'::text)) OR ((("ActionCode")::text = 'RESOLVE'::text) AND ("FromStatus"  = ANY (ARRAY['Open'::character varying, 'Acknowledged'::character varying])) AND (("ToStatus")::text = 'Resolved'::text)) OR ((("ActionCode")::text = 'SOURCE_RESOLVED'::text) AND ("FromStatus"  = ANY (ARRAY['Open'::character varying, 'Acknowledged'::character varying])) AND (("ToStatus")::text = 'Resolved'::text)) OR ((("ActionCode")::text = 'DISMISS'::text) AND ("FromStatus"  = ANY (ARRAY['Open'::character varying, 'Acknowledged'::character varying])) AND (("ToStatus")::text = 'Dismissed'::text)) OR (("ActionCode"  = ANY (ARRAY['REOPEN'::character varying, 'REOPENED'::character varying])) AND ("FromStatus"  = ANY (ARRAY['Acknowledged'::character varying, 'Resolved'::character varying, 'Dismissed'::character varying])) AND (("ToStatus")::text = 'Open'::text)))),
    CONSTRAINT "CK_commercial_exception_events_Status" CHECK (((("FromStatus" IS NULL) OR ("FromStatus"  = ANY (ARRAY['Open'::character varying, 'Acknowledged'::character varying, 'Resolved'::character varying, 'Dismissed'::character varying]))) AND ("ToStatus"  = ANY (ARRAY['Open'::character varying, 'Acknowledged'::character varying, 'Resolved'::character varying, 'Dismissed'::character varying])))),
    CONSTRAINT "CK_commercial_exception_events_Version" CHECK ((("FromVersion" >= 0) AND ("ToVersion" = ("FromVersion" + 1))))
);

