    "EvidenceHash" character varying(64) NOT NULL,
    "PriorityScore" integer NOT NULL,
    "PriorityBand" character varying(30) NOT NULL,
    "Confidence" numeric(5,4) NOT NULL,
    "Completeness" numeric(5,4) NOT NULL,
    "SampleSize" integer NOT NULL,
    "RecommendedActionCode" character varying(80) NOT NULL,
    "RecommendedActionLabel" character varying(160) NOT NULL,
    "RationaleJson" jsonb NOT NULL,
    "CohortKey" character varying(100) NOT NULL,
    "Mode" character varying(20) NOT NULL,
    "GeneratedAtUtc" timestamp without time zone NOT NULL,
    "SupersedesRecommendationId" bigint,
    "ComponentsJson" jsonb NOT NULL,
    "ExpectedCommercialValue" numeric(20,4),
    "ExpectedCommercialValueCurrency" character varying(12),
    CONSTRAINT "CK_opportunity_recommendations_Band" CHECK (("PriorityBand"  = ANY (ARRAY['Low'::character varying, 'Medium'::character varying, 'High'::character varying, 'Critical'::character varying]))),
    CONSTRAINT "CK_opportunity_recommendations_Completeness" CHECK ((("Completeness" >= (0)::numeric) AND ("Completeness" <= (1)::numeric))),
    CONSTRAINT "CK_opportunity_recommendations_ComponentsObject" CHECK (COALESCE(((jsonb_typeof("ComponentsJson") = 'object'::text) AND ("ComponentsJson" ? 'signals'::text) AND ("ComponentsJson" ? 'status'::text) AND ("ComponentsJson" ? 'currentBlocker'::text) AND (jsonb_typeof(("ComponentsJson" -> 'signals'::text)) = 'array'::text) AND (jsonb_typeof(("ComponentsJson" -> 'status'::text)) = 'string'::text) AND (jsonb_typeof(("ComponentsJson" -> 'currentBlocker'::text)) = 'string'::text)), false)),
    CONSTRAINT "CK_opportunity_recommendations_Confidence" CHECK ((("Confidence" >= (0)::numeric) AND ("Confidence" <= (1)::numeric))),
    CONSTRAINT "CK_opportunity_recommendations_EcvCurrency" CHECK (COALESCE((("ComponentsJson" ? 'expectedCommercialValue'::text) AND ("ComponentsJson" ? 'currency'::text) AND (("ExpectedCommercialValue" IS NULL) = ("ExpectedCommercialValueCurrency" IS NULL)) AND (("ExpectedCommercialValueCurrency" IS NULL) OR (("ExpectedCommercialValueCurrency")::text ~ '^[A-Z]{3}$'::text)) AND
CASE
    WHEN ("ExpectedCommercialValue" IS NULL) THEN ((("ComponentsJson" -> 'expectedCommercialValue'::text) = 'null'::jsonb) AND (("ComponentsJson" -> 'currency'::text) = 'null'::jsonb))
    ELSE ((jsonb_typeof(("ComponentsJson" -> 'expectedCommercialValue'::text)) = 'number'::text) AND ((("ComponentsJson" ->> 'expectedCommercialValue'::text))::numeric = "ExpectedCommercialValue") AND (("ComponentsJson" ->> 'currency'::text) = ("ExpectedCommercialValueCurrency")::text))
END), false)),
    CONSTRAINT "CK_opportunity_recommendations_EcvNonNegative" CHECK ((("ExpectedCommercialValue" IS NULL) OR ("ExpectedCommercialValue" >= (0)::numeric))),
    CONSTRAINT "CK_opportunity_recommendations_EvidenceHash" CHECK ((length(("EvidenceHash")::text) = 64)),
    CONSTRAINT "CK_opportunity_recommendations_Generated" CHECK (("GeneratedAtUtc" >= "EvidenceCutoffAtUtc")),
    CONSTRAINT "CK_opportunity_recommendations_LeadVersion" CHECK (("LeadVersion" >= 1)),
    CONSTRAINT "CK_opportunity_recommendations_Mode" CHECK ((("Mode")::text = 'Shadow'::text)),
    CONSTRAINT "CK_opportunity_recommendations_SampleSize" CHECK (("SampleSize" >= 0)),
