    created_on timestamp with time zone NOT NULL,
    updated_on timestamp with time zone NOT NULL,
    ocr_cost_status character varying(32) NOT NULL,
    processing_cost_amount numeric(18,6),
    processing_cost_currency character(3),
    processing_cost_status character varying(32) NOT NULL,
    ocr_page_count integer DEFAULT 0 NOT NULL,
    ocr_status character varying(32) DEFAULT 'NotRequired'::character varying NOT NULL,
    ocr_truncated boolean DEFAULT false NOT NULL,
    processing_path character varying(32) DEFAULT 'LegacyUnknown'::character varying NOT NULL,
    CONSTRAINT ck_extraction_runs_attempt CHECK ((attempt_number > 0)),
    CONSTRAINT ck_extraction_runs_business_unit CHECK ((business_unit_id > 0)),
    CONSTRAINT ck_extraction_runs_completion CHECK ((((status  = ANY (ARRAY['Completed'::character varying, 'Failed'::character varying])) AND (completed_on IS NOT NULL)) OR ((status  <> ALL (ARRAY['Completed'::character varying, 'Failed'::character varying])) AND (completed_on IS NULL)))),
    CONSTRAINT ck_extraction_runs_cost CHECK ((((processing_cost_amount IS NULL) AND (processing_cost_currency IS NULL)) OR ((processing_cost_amount >= (0)::numeric) AND (processing_cost_currency ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT ck_extraction_runs_counts CHECK (((page_count >= 0) AND (region_count >= 0) AND (inquiry_count >= 0) AND (line_item_count >= 0) AND (evidence_count >= 0) AND (finding_count >= 0))),
    CONSTRAINT ck_extraction_runs_failure CHECK (((((status)::text = 'Failed'::text) AND (failure_reason IS NOT NULL)) OR (((status)::text <> 'Failed'::text) AND (failure_reason IS NULL)))),
    CONSTRAINT ck_extraction_runs_job CHECK ((extraction_job_id > 0)),
    CONSTRAINT ck_extraction_runs_ocr_evidence CHECK (((ocr_page_count >= 0) AND (((ocr_status)::text <> 'NotRequired'::text) OR ((ocr_page_count = 0) AND (ocr_truncated = false)))))
);


