--
-- Name: source_document_occurrences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.source_document_occurrences (
    id bigint NOT NULL,
    business_unit_id bigint NOT NULL,
    source_document_id bigint NOT NULL,
    corpus_id bigint NOT NULL,
    extraction_job_id bigint,
    idempotency_key character varying(256) NOT NULL,
    source_metadata jsonb NOT NULL,
    received_on timestamp with time zone NOT NULL,
    intake_status character varying(32) DEFAULT 'Accepted'::character varying NOT NULL,
    last_error_code character varying(128),
    logical_group_key character varying(256),
    updated_on timestamp with time zone DEFAULT now() NOT NULL,
    last_error_category character varying(64),
    last_error_details jsonb,
    bytes_uploaded bigint DEFAULT 0 NOT NULL,
    cost_status character varying(48) DEFAULT 'LOCAL_COMPUTE_UNPRICED'::character varying NOT NULL,
    estimated_processing_avoided numeric(18,6) DEFAULT 0.0 NOT NULL,
    external_model_reused boolean DEFAULT false NOT NULL,
    external_processing_cost numeric(18,6) DEFAULT 0.0 NOT NULL,
    hashing_duration_ms bigint DEFAULT 0 NOT NULL,
    local_compute_cost numeric(18,6) DEFAULT 0.0 NOT NULL,
    local_model_reused boolean DEFAULT false NOT NULL,
    malware_scan_rerun boolean DEFAULT false NOT NULL,
    malware_scan_reused boolean DEFAULT false NOT NULL,
    ocr_reused boolean DEFAULT false NOT NULL,
    original_occurrence_id bigint,
    outcome_state character varying(48) DEFAULT 'NONE'::character varying NOT NULL,
    parser_reused boolean DEFAULT false NOT NULL,
    processing_reused boolean DEFAULT false NOT NULL,
    storage_logical_bytes bigint DEFAULT 0 NOT NULL,
    storage_physical_bytes bigint DEFAULT 0 NOT NULL,
    total_actual_cost numeric(18,6) DEFAULT 0.0 NOT NULL,
    CONSTRAINT ck_source_document_occurrences_business_unit CHECK ((business_unit_id > 0)),
    CONSTRAINT ck_source_document_occurrences_intake_status CHECK ((intake_status  = ANY (ARRAY['Accepted'::character varying, 'AwaitingSecurityScan'::character varying, 'Queued'::character varying, 'Processing'::character varying, 'Retryable'::character varying, 'Resolved'::character varying, 'ReviewRequired'::character varying, 'Rejected'::character varying, 'DeadLetter'::character varying]))),
    CONSTRAINT ck_source_document_occurrences_original CHECK (((original_occurrence_id IS NULL) OR (original_occurrence_id <> id))),
    CONSTRAINT ck_source_document_occurrences_outcome_state CHECK ((outcome_state  = ANY (ARRAY['NONE'::character varying, 'EXACT_DUPLICATE_PENDING_SECURITY'::character varying, 'EXACT_DUPLICATE_CONFIRMED'::character varying, 'BUSINESS_DUPLICATE_CONFIRMED'::character varying, 'DUPLICATE_RESCAN_REQUIRED'::character varying, 'REVISION'::character varying, 'POSSIBLE_MATCH'::character varying, 'SECURITY_SCAN_BLOCKED'::character varying, 'MALWARE_DETECTED'::character varying, 'UNSUPPORTED_FORMAT'::character varying, 'SOURCE_OBJECT_UNAVAILABLE'::character varying, 'EVIDENCE_INTEGRITY_FAILURE'::character varying, 'AI_NOT_AUTHORIZED'::character varying]))),
    CONSTRAINT ck_source_document_occurrences_resource_costs CHECK (((local_compute_cost >= (0)::numeric) AND (external_processing_cost >= (0)::numeric) AND (total_actual_cost >= (0)::numeric) AND (estimated_processing_avoided >= (0)::numeric) AND (length((cost_status)::text) > 0))),
    CONSTRAINT ck_source_document_occurrences_resource_counts CHECK (((bytes_uploaded >= 0) AND (hashing_duration_ms >= 0) AND (storage_physical_bytes >= 0) AND (storage_logical_bytes >= 0)))
