--
-- Name: source_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.source_documents (
    id bigint NOT NULL,
    business_unit_id bigint NOT NULL,
    corpus_id bigint NOT NULL,
    extraction_job_id bigint,
    content_hash character(64) NOT NULL,
    original_file_name character varying(512) NOT NULL,
    detected_mime_type character varying(255) NOT NULL,
    object_bucket character varying(255) NOT NULL,
    object_key character varying(1024) NOT NULL,
    object_version character varying(255) NOT NULL,
    byte_size bigint NOT NULL,
    page_count integer NOT NULL,
    security_status character varying(32) NOT NULL,
    processing_status character varying(32) NOT NULL,
    created_on timestamp with time zone NOT NULL,
    updated_on timestamp with time zone NOT NULL,
    malware_scanned_on timestamp with time zone,
    malware_scanner_engine character varying(128),
    malware_signature_version character varying(256),
    malware_verdict_status character varying(32),
    bytes_purged_on timestamp with time zone,
    purge_policy_code character varying(64),
    purge_reason character varying(256),
    purge_requested_on timestamp with time zone,
    purge_state character varying(24) DEFAULT 'Present'::character varying NOT NULL,
    purged_by_user_id bigint,
    purged_byte_count bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_source_documents_business_unit CHECK ((business_unit_id > 0)),
    CONSTRAINT ck_source_documents_byte_size CHECK ((byte_size >= 0)),
    CONSTRAINT ck_source_documents_content_hash CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_source_documents_malware_verdict CHECK ((((malware_verdict_status IS NULL) AND (malware_scanned_on IS NULL)) OR ((malware_verdict_status  = ANY (ARRAY['Clean'::character varying, 'Infected'::character varying, 'Unavailable'::character varying, 'Error'::character varying])) AND (malware_scanned_on IS NOT NULL) AND (malware_scanner_engine IS NOT NULL)))),
    CONSTRAINT ck_source_documents_page_count CHECK ((page_count >= 0)),
    CONSTRAINT ck_source_documents_purge_completion CHECK ((((purge_state)::text = 'Purged'::text) = (bytes_purged_on IS NOT NULL))),
    CONSTRAINT ck_source_documents_purge_intent CHECK ((((purge_state)::text = 'Present'::text) = (purge_requested_on IS NULL))),
    CONSTRAINT ck_source_documents_purge_state CHECK ((purge_state  = ANY (ARRAY['Present'::character varying, 'PurgeRequested'::character varying, 'Purged'::character varying]))),
    CONSTRAINT ck_source_documents_purged_byte_count CHECK ((purged_byte_count >= 0))
);


