--
-- Name: supplier_shipments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS public.supplier_shipments (
    "Id" bigint NOT NULL,
    "BusinessUnitId" bigint NOT NULL,
    "SupplierPurchaseOrderId" bigint NOT NULL,
    "ShipmentNumber" character varying(100) NOT NULL,
    "Milestone" character varying(32) NOT NULL,
    "MilestoneOccurredOn" date NOT NULL,
    "ReadyAtFactoryOn" date,
    "DepartedOriginOn" date,
    "InTransitOn" date,
    "ArrivedSaudiPortOn" date,
    "CustomsClearanceOn" date,
    "ReceivedAtWarehouseOn" date,
    "CancelledOn" date,
    "CancellationReason" character varying(1000),
    "PortOfEntryId" bigint,
    "CarrierName" character varying(255),
    "TrackingReference" character varying(160),
    "TrackingSource" character varying(16) NOT NULL,
    "EtaDate" date,
    "EtaUpdatedOn" timestamp without time zone,
    "EtaUpdatedBy" character varying(255),
    "MaterialAvailableDate" date,
    "MaterialAvailableBasisKind" character varying(32),
    "MaterialAvailableBasisDate" date,
    "AppliedCustomsClearanceDays" integer,
    "AppliedPutawayDays" integer,
    "MaterialAvailableComputedOn" timestamp without time zone,
    "MaterialAvailableUnavailableReason" character varying(500),
    "IdempotencyKey" character varying(160) NOT NULL,
    "RequestHash" character varying(64) NOT NULL,
    "Version" bigint DEFAULT 1 NOT NULL,
    "CreatedOn" timestamp without time zone NOT NULL,
    "CreatedBy" character varying(255) NOT NULL,
    "ModifiedOn" timestamp without time zone,
    "ModifiedBy" character varying(255),
    CONSTRAINT "CK_supplier_shipments_AppliedLeadDays" CHECK (((("AppliedCustomsClearanceDays" IS NULL) OR ("AppliedCustomsClearanceDays" >= 0)) AND (("AppliedPutawayDays" IS NULL) OR ("AppliedPutawayDays" >= 0)))),
    CONSTRAINT "CK_supplier_shipments_ArrivalLocation" CHECK ((("ArrivedSaudiPortOn" IS NULL) OR ("PortOfEntryId" IS NOT NULL))),
    CONSTRAINT "CK_supplier_shipments_Cancellation" CHECK (((("Milestone")::text <> 'CANCELLED'::text) OR (("CancelledOn" IS NOT NULL) AND ("CancellationReason" IS NOT NULL)))),
    CONSTRAINT "CK_supplier_shipments_Milestone" CHECK (("Milestone"  = ANY (ARRAY['READY_AT_FACTORY'::character varying, 'DEPARTED_ORIGIN'::character varying, 'IN_TRANSIT'::character varying, 'ARRIVED_SAUDI_PORT'::character varying, 'CUSTOMS_CLEARANCE'::character varying, 'RECEIVED_AT_WAREHOUSE'::character varying, 'CANCELLED'::character varying]))),
    CONSTRAINT "CK_supplier_shipments_TrackingSource" CHECK (("TrackingSource"  = ANY (ARRAY['MANUAL'::character varying, 'CARRIER_API'::character varying])))
);

